 if target:
  moves[p.name]=str(target.relative_to(hw));p.rename(target)
(backup/'moves.json').write_text(json.dumps(moves,indent=2)+'\n')
print(json.dumps({'raw_files_copied':len(files),'copies_identical':True,'moves':moves,'aggregate_rows':6},indent=2))
